from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class Agentv1HttpClient(HttpClient):
    """ This class provides a client for the Agent v1 API """
    def __init__(self, base_url, connection_alias):
        super(Agentv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/agent/v1"

    def reset_rannic(self, timeout=30, rannic_r_dn=None, graceful_cell_shutdown=False):
        endpoint = '/rannics/operations/reset'
        payload = {"rannicRDn": rannic_r_dn, "reason": "Manual reboot", "gracefulCellShutdown": graceful_cell_shutdown}

        return self._send_post_request(endpoint=endpoint, json=payload, timeout=timeout)

    def get_ranic_reset_operation_status(self, operation_id, timeout=30):
        endpoint = f'/rannics/operations/reset/{operation_id}'

        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_ranic_reset_operation(self, operation_id, timeout=30):
        endpoint = f'/rannics/operations/reset/{operation_id}'

        headers = {
            "accept": "*/*"
        }

        self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_pod_sync_status(self, pod_id, timeout=30):
        endpoint = f'/pods/{pod_id}/sync-status'
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def reset_vdu(self, timeout, graceful_cell_shutdown=False):
        endpoint = "/vdu/operations/resets"
        headers = {
            "accept": "application/json",
            "content-type": "application/json"
        }
        payload = {
            "gracefulCellShutdown": graceful_cell_shutdown
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)

    def get_reset_vdu_operation_status(self, operation_id, timeout):
        endpoint = f"/vdu/operations/resets/{operation_id}"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
